"use strict";(self.webpackChunkwebsite=self.webpackChunkwebsite||[]).push([["3890"],{9198(e,t,n){n.r(t),n.d(t,{metadata:()=>a,default:()=>d,frontMatter:()=>i,contentTitle:()=>r,toc:()=>u,assets:()=>c});var a=JSON.parse('{"id":"reference/account","title":"Account Management & Billing","description":"av \xb7 imported from live Hugo on 2026-10-07. Guides stay latest. Original page.","source":"@site/docs/reference/account.md","sourceDirName":"reference","slug":"/reference/account","permalink":"/personal-av-docs/docs/reference/account","draft":false,"unlisted":false,"editUrl":"https://github.com/andreyjv/personal-av/tree/docs/documentation-revamp/PRD_documentation-revamp/website/docs/reference/account.md","tags":[],"version":"current","sidebarPosition":99,"frontMatter":{"title":"Account Management & Billing","sidebar_label":"Account Management & Billing","sidebar_position":99,"edition":"av","source":"https://doc.airvantage.net/av/reference/account","format":"md"}}'),o=n(4848),s=n(8453);let i={title:"Account Management & Billing",sidebar_label:"Account Management & Billing",sidebar_position:99,edition:"av",source:"https://doc.airvantage.net/av/reference/account",format:"md"},r,c={},u=[];function m(e){let t={a:"a",p:"p",strong:"strong",...(0,s.R)(),...e.components};return(0,o.jsxs)(o.Fragment,{children:[(0,o.jsxs)(t.p,{children:[":::note Edition\n",(0,o.jsx)(t.strong,{children:"av"})," \xb7 imported from live Hugo on 2026-10-07. Guides stay latest. ",(0,o.jsx)(t.a,{href:"https://doc.airvantage.net/av/reference/account",children:"Original page"}),".\n:::"]}),"\n",(0,o.jsxs)(t.p,{children:["Account Management & Billing\nAPI & Connectors\nWeb Services API\nCloud Connectors\nCloud Connectors Format\nMore\nGeneral FAQ\nAVPhone FAQ\nGDPR FAQ\nProduct Page\nForum\nSearching...\nMatching results\nAccount Management & Billing\nThe Account Management application provides a comprehensive vision of datapoint consumption by your fleet of systems, including detailed drill-downs per subaccount in order to anticipate their data consumption and to avoid surprises related to billing.\nThis topic explains the tools offered by the application, as displayed on the three tabs. It also provides links to several How To topics covering the most common tasks and issues you are likely to encounter during your work routine.\nInitializing Table Of Contents...\nHow does AirVantage Platform calculate your consumption\nCalculations are based on the number of unique devices that have been activated during the month. That means if you activate a system, the counter increases by 1 (whether or not you later deactivate it).\nIf you reactivate a system deactivated during the current month, the counter does not increase.\nExample:\nyou have 20 deployed systems in your fleet for the 10 first days of the month. You have 20 activated systems.\nyou activate 2 new systems. Counter increases to 22 systems.\nyou disactivate a system. Counter stays at 22 systems.\nyou activate a new system. Counter increases to 23 systems.\nYou reactivate the system previously disactivated. Counter stays at 23 systems.\nNote only systems in \u201CReady\u201D or \u201CDeployed\u201D states are seen as Activated systems:\nInventory\n: System registered (complete or partially created) in AirVantage\nReady\n: System activated ready for deployment. AirVantage can start monitoring the system\nDeployed\n: AirVantage automatically switches the system state to Deployed when a Ready system first communicates, whatever the protocol.\nMaintenance\n: AirVantage no longer monitors the system, i.e does not take into account a communication from the system when in Maintenance.\nThis billing distinction between systems has been introduced to simplify the system deactivation/activation process. In some cases it may save you money and/or administration effort. For instance, if you want to remove a system from operation (e.g. for maintenance purpose, or if you simply do not want it to incur unnecessary charges), you can simply change its status to \u201CMaintenance\u201D, rather than needing to delete it from the system and then to add it back later.\nSee\nhere\nfor more details on switching to maintenance.\nSee\nhere\nfor more details about how to check your consumption.\nAccess & Login\nAccount Management is a stand-alone web application connected to the AirVantage Platform.\nYou can access it by:\nClicking\nAccount\non the top navigation menu.\nUsing the the following url:\n",(0,o.jsx)(t.a,{href:"https://eu.airvantage.net/accounts",children:"https://eu.airvantage.net/accounts"}),"\nClicking\nMy Account\non the user menu:\nYou can log in using the same credentials as those you use for AirVantage Platform. Please note that you will only be able to access the Account Management web application if you are an Admin user of your company account.\nFrom Account Management, you can return to the main application by clicking on the AirVantage logo at the top of the page.\nWho can access consumption information?\nEvery user of your company can access the\nDetails tab\n, but only Administrators can access the\nDashboard tab\nand\nSub-account tab\nEvery company has a Semtech Administrator by default. It is used by the Semtech Support team.\nIf you wish to remove the Semtech Administrator from the Administrator\u2019s list, please contact your Semtech Salesperson.\nDashboard tab\nThis tab gives you a complete and global vision of your fleet of connected systems.\nYou can use these widgets to analyze your fleet\u2019s data consumption trend.\nSee\nHow to check data consumption?\nThe widgets are:\nCurrent Month Billing Summary widget\nSystems widget\nDatapoints reception widget.\nUnderstanding Datapoints...\nA Data Point is a discrete value transmitted from a machine to AirVantage.(e.g. temperature readings, consumption values). In the temperature example, a Data Point is 1 temperature reading taken at a given point in time.\nA Data point can be a discrete value transmitted from the firmware module to AirVantage (eg. RSSI).\nIt doesn\u2019t include summarized values of your Data Points (Average, max, min by week, month, year).\nData Consumption details reports widget: See\nHow to integrate my fleet consumption with my IT system?\nMy company details tab\nThis is the tab where you can check and update your company account details and information. Currently this consists of company name, uid and company logo, as used by the AirVantage Platform. You can modify the logo here if you wish.\nSub-accounts tab\nSo that you can keep your systems organized and make reports easy to compile and read, Account Management offers you the option to set up sub-accounts under your own account groupings. Use this feature, for instance, to track data consumption and account status for your business units, partners or any other group of systems you care to define within your company.\nThe grid displays all your sub-accounts, along with related account information, such as their number of activated systems and Datapoint consumption, and whether the sub-account is are active or suspended.\nSeveral filtering and sorting capabilities are available to help you easily identify any issues, such as customers who need to pay their bills.\nFrom the sub-account grid, you can also activate or suspend an account. To do so, toggle the relevant\nswitch. A window appears asking you to confirm the activation or deactivation of the sub-account.\nSee also\nHow to manage sub-accounts?\nSub-account details\nClicking on a specific sub-account in the grid displays a drill-down to the detailed view of the sub-account. The following widgets are displayed:\nCurrent month billing summary\nSystems\nDatapoints reception.\nUnderstanding Datapoints\u2026\nA Data Point is a discrete value transmitted from a machine to AirVantage.(e.g. temperature readings, consumption values). In the temperature example, a Data Point is 1 temperature reading taken at a given point in time.\nA Data point can be a discrete value transmitted from the firmware module to AirVantage (eg. RSSI).\nIt doesn\u2019t include summarized values of your Data Points (Average, max, min by week, month, year).\nSee also\nHow to use the app for a partner sub-account?\nBilling\nSee\nhere\nfor more details on billing.\nHow-Tos\nThis section provides you with helpful procedures for common tasks.\nHow to check data consumption?\nHow to integrate my fleet consumption with my IT system?\nHow to manage sub-accounts?\nHow to use the application for a partner sub-account?\nWho can access consumption information?"]})]})}function d(e={}){let{wrapper:t}={...(0,s.R)(),...e.components};return t?(0,o.jsx)(t,{...e,children:(0,o.jsx)(m,{...e})}):m(e)}},8453(e,t,n){n.d(t,{R:()=>i,x:()=>r});var a=n(6540);let o={},s=a.createContext(o);function i(e){let t=a.useContext(s);return a.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(o):e.components||o:i(e.components),a.createElement(s.Provider,{value:t},e.children)}}}]);